flowchart TB
  OPS(["運用チーム"])
  CS@{ svc: "AWS CloudFormation", label: "✔ B: 変更セットを作って確認" }
  CF@{ svc: "AWS CloudFormation", label: "スタックの更新" }
  S3@{ svc: "Amazon S3", label: "✔ B: 監査ログのバケット（Retain）" }
  RDS@{ svc: "Amazon RDS", label: "DB インスタンス" }
  OPS --> CS
  CS == "確認後に実行" ==> CF
  OPS -. "⚠ A: 直接 UpdateStack、事前に見えない" .-> CF
  CF --> RDS
  CF == "✔ B: 外れても残る" ==> S3
  CF -. "⚠ C・D: 指定なしだと消える（既定は Snapshot ではない）" .-> S3
